# Increase recursion depth just in case, though we'll use iterative BFS/DFS
sys.setrecursionlimit(2000000)

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    T = int(next(iterator))
    results = []

    MOD = 998244353

    for _ in range(T):
        H = int(next(iterator))
        W = int(next(iterator))
        grid = []
        for _ in range(H):
            grid.append(next(iterator))

        # Check even A's in columns
        col_a_count = [0] * W
        for j in range(W):
            for i in range(H):
                if grid[i][j] == 'A':
                    col_a_count[j] += 1
            if col_a_count[j] % 2 != 0:
                results.append(0)
                break
        else:
            # Check even A's in rows
            row_a_count = [0] * H
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == 'A':
                        row_a_count[i] += 1
                if row_a_count[i] % 2 != 0:
                    results.append(0)
                    break
            else:
                # Compute p and q
                # p[i][j] is parity of A's in col j from row 0 to i-1
                p = [[0] * W for _ in range(H)]
                for j in range(W):
                    current = 0
                    for i in range(H):
                        p[i][j] = current
                        if grid[i][j] == 'A':
                            current ^= 1

                # q[i][j] is parity of A's in row i from col 0 to j-1
                q = [[0] * W for _ in range(H)]
                for i in range(H):
                    current = 0
                    for j in range(W):
                        q[i][j] = current
                        if grid[i][j] == 'A':
                            current ^= 1

                # Build graph
                # Nodes 0..W-1 for columns, W..W+H-1 for rows
                num_nodes = H + W
                adj = [[] for _ in range(num_nodes)]

                for i in range(H):
                    for j in range(W):
                        if grid[i][j] == 'B':
                            w = p[i][j] ^ q[i][j]
                            u = j
                            v = W + i
                            adj[u].append((v, w))
                            adj[v].append((u, w))

                # Find connected components and check consistency
                visited = [False] * num_nodes
                assigned = [0] * num_nodes
                num_components = 0
                possible = True

                for start_node in range(num_nodes):
                    if not visited[start_node]:
                        num_components += 1
                        # BFS
                        queue = [start_node]
                        visited[start_node] = True
                        assigned[start_node] = 0
                        idx = 0
                        while idx < len(queue):
                            u = queue[idx]
                            idx += 1
                            for v, w in adj[u]:
                                if not visited[v]:
                                    visited[v] = True
                                    assigned[v] = assigned[u] ^ w
                                    queue.append(v)
                                else:
                                    if assigned[v] != assigned[u] ^ w:
                                        possible = False
                                        break
                            if not possible:
                                break
                        if not possible:
                            break

                if possible:
                    ans = pow(2, num_components, MOD)
                    results.append(ans)
                else:
                    results.append(0)

    print('\n'.join(map(str, results)))

