import sys
import heapq

# Increase recursion depth to handle deep segment tree recursion if necessary
sys.setrecursionlimit(10**6)

def solve():
    # Fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
        Q = int(next(iterator))
    except StopIteration:
        return

    S = [0] * (M + 1)
    T = [0] * (M + 1)
    types = [0] * (M + 1) # 1 for up (S < T), -1 for down (S > T)

    for i in range(1, M + 1):
        S[i] = int(next(iterator))
        T[i] = int(next(iterator))
        if S[i] < T[i]:
            types[i] = 1
        else:
            types[i] = -1
            # Normalize to u < v for interval processing
            S[i], T[i] = T[i], S[i] 

    def get_next_cross(intervals, M, N):
        # Returns an array where next_cross[i] is the smallest j > i that crosses i
        # within the same type. If no crossing, inf.
        next_cross = [float('inf')] * (M + 1)
        tree = [float('inf')] * (4 * N + 1)
        candidates = [[] for _ in range(N + 1)]

        def update(node, l, r, pos, val):
            if l == r:
                tree[node] = val
                return
            mid = (l + r) // 2
            if pos <= mid:
                update(2 * node, l, mid, pos, val)
            else:
                update(2 * node + 1, mid + 1, r, pos, val)
            tree[node] = min(tree[2 * node], tree[2 * node + 1])

        def find_first(node, l, r, ql, qr, limit):
            # Find leftmost position in [ql, qr] with value < limit
            if r < ql or l > qr or tree[node] >= limit:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            res = find_first(2 * node, l, mid, ql, qr, limit)
            if res != -1:
                return res
            return find_first(2 * node + 1, mid + 1, r, ql, qr, limit)

        for s_j, t_j, j in intervals:
            ql, qr = s_j + 1, t_j - 1
            if ql <= qr:
                t = find_first(1, 1, N, ql, qr, s_j)
                if t != -1:
                    # Found a crossing interval ending at t
                    s_i, i = heapq.heappop(candidates[t])
                    next_cross[i] = j
                    # Update tree leaf t
                    if candidates[t]:
                        new_val = candidates[t][0][0]
                    else:
                        new_val = float('inf')
                    update(1, 1, N, t, new_val)

            heapq.heappush(candidates[t_j], (s_j, j))
            update(1, 1, N, t_j, candidates[t_j][0][0])

        return next_cross

    up_intervals = []
    down_intervals = []
    for i in range(1, M + 1):
        if types[i] == 1:
            up_intervals.append((S[i], T[i], i))
        else:
            down_intervals.append((S[i], T[i], i))

    next_cross_up = get_next_cross(up_intervals, M, N)
    next_cross_down = get_next_cross(down_intervals, M, N)

    # Combine results: a crossing is invalid only if it's within the same type
    final_next_cross = [float('inf')] * (M + 1)
    for i in range(1, M + 1):
        final_next_cross[i] = min(next_cross_up[i], next_cross_down[i])

    # Build Sparse Table for RMQ
    LOG = [0] * (M + 2)
    for i in range(2, M + 2):
        LOG[i] = LOG[i // 2] + 1
    K = LOG[M] + 1
    st = [[float('inf')] * (M + 1) for _ in range(K)]
    for i in range(1, M + 1):
        st[0][i] = final_next_cross[i]
    for k in range(1, K):
        length = 1 << (k - 1)
        for i in range(1, M - (1 << k) + 2):
            st[k][i] = min(st[k-1][i], st[k-1][i + length])

    def query_rmq(l, r):
        if l > r: return float('inf')
        k = LOG[r - l + 1]
        return min(st[k][l], st[k][r - (1 << k) + 1])

    results = []
    for _ in range(Q):
        L = int(next(iterator))
        R = int(next(iterator))
        # If min next_cross in range is <= R, it means there is a crossing pair fully inside [L, R]
        if query_rmq(L, R) <= R:
            results.append("No")
        else:
            results.append("Yes")

    print('\n'.join(results))

