class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[(sum, parity)] = max_product
        # parity 0: even length subsequence, parity 1: odd length subsequence
        dp = {(0, 0): 1}

        for x in nums:
            new_dp = dp.copy()
            for (s, p), prod in dp.items():
                np = prod * x
                if np > limit:
                    continue
                # If current length is even (p=0), next element is at even index -> add
                # If current length is odd (p=1), next element is at odd index -> subtract
                ns = s + x if p == 0 else s - x
                np2 = 1 - p
                if np > new_dp.get((ns, np2), -1):
                    new_dp[(ns, np2)] = np
            dp = new_dp

        # We need a non-empty subsequence, so we check both parities.
        # However, dp[(0, 0)] = 1 corresponds to the empty subsequence.
        ans = max(dp.get((k, 1), -1), dp.get((k, 0), -1))

        # If k == 0 and the best product is 1, it might be from the empty subsequence.
        # We invalidate it if dp[(0, 0)] is still 1 (meaning no non-empty even-length subsequence reached it).
        if k == 0 and ans == 1 and dp.get((0, 0), -1) == 1:
            ans = -1

        return ans

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def F(n):
            if n <= 0:
                return 0
            total = 0
            p = 1
            d = 0
            while p <= n:
                upper = 4 * p - 1
                if upper > n:
                    upper = n
                total += (upper - p + 1) * (d + 1)
                p *= 4
                d += 1
            return total

        ans = 0
        for l, r in queries:
            s = F(r) - F(l - 1)
            ans += (s + 1) // 2
        return ans

from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N):
            if N == 0: return 0
            digits = list(map(int, str(N)))
            n = len(digits)
            total = 0

            # Iterate over all possible digit sums S
            for S in range(1, 9 * n + 1):
                @lru_cache(None)
                def dp(idx, current_sum, current_prod_mod, is_less, is_started):
                    # Pruning: sum already exceeds target
                    if current_sum > S:
                        return 0
                    # Pruning: even with max digits left, can't reach target sum
                    if current_sum + (n - idx) * 9 < S:
                        return 0

                    if idx == n:
                        # Valid if sum matches, product divisible by sum (mod S == 0), and number is positive
                        return 1 if (current_sum == S and current_prod_mod == 0 and is_started) else 0

                    limit = digits[idx] if not is_less else 9
                    res = 0
                    for d in range(limit + 1):
                        new_is_less = is_less or (d < limit)
                        new_is_started = is_started or (d > 0)

                        if not new_is_started:
                            # Still placing leading zeros
                            res += dp(idx + 1, 0, 0, new_is_less, False)
                        else:
                            new_sum = current_sum + d
                            if new_sum > S:
                                continue
                            # Multiply current product modulo S by the new digit
                            new_prod_mod = (current_prod_mod * d) % S
                            res += dp(idx + 1, new_sum, new_prod_mod, new_is_less, True)

                    return res

                # Fixed: initial product modulo is 1 (multiplicative identity)
                total += dp(0, 0, 1, False, False)
                dp.cache_clear()
            return total

        return count(r) - count(l - 1)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = [None] * L

        # 1. Process 'T' constraints to fix characters
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    j = i + k
                    if word[j] is not None and word[j] != str2[k]:
                        return ""
                    word[j] = str2[k]

        # 2. Initialize match_count for 'F' constraints
        match_count = [0] * n
        for i in range(n):
            if str1[i] == 'F':
                for k in range(m):
                    j = i + k
                    if word[j] == str2[k]:
                        match_count[i] += 1
                if match_count[i] == m:
                    return ""

        # 3. Iterate through positions greedily
        for j in range(L):
            if word[j] is None:
                # Find characters forbidden by critical 'F' constraints
                forbidden = set()
                start_i = max(0, j - m + 1)
                end_i = min(j, n - 1)
                for i in range(start_i, end_i + 1):
                    if str1[i] == 'F' and match_count[i] == m - 1:
                        forbidden.add(str2[j - i])

                # Pick the lexicographically smallest valid character
                chosen = None
                for c in "abcdefghijklmnopqrstuvwxyz":
                    if c not in forbidden:
                        chosen = c
                        break
                if chosen is None:
                    return ""
                word[j] = chosen

            # Update match_count for 'F' constraints covering position j
            start_i = max(0, j - m + 1)
            end_i = min(j, n - 1)
            for i in range(start_i, end_i + 1):
                if str1[i] == 'F':
                    if word[j] == str2[j - i]:
                        match_count[i] += 1
                        if match_count[i] == m:
                            return ""

        return "".join(word)

