    # dp[interval_idx][d0] = count
    dp = [[0] * 4 for _ in range(6)]

    # Initialize for i=0
    start_d0_range = range(3) if not is_S[0] else range(4)
    for d0 in start_d0_range:
        dp[3][d0] = 1

    # Iterate i from 0 to N-2
    for i in range(N - 1):
        new_dp = [[0] * 4 for _ in range(6)]
        next_is_S = is_S[i+1]
        d_vals = range(4) if next_is_S else range(3)

        for ii in range(6):
            for d0 in range(4):
                count = dp[ii][d0]
                if count == 0:
                    continue

                min_p, max_p = idx_to_interval[ii]

                for d_val in d_vals:
                    n_min, n_max = 2, -2
                    found = False

                    deltas = ([d_val - 1, d_val - 2] if next_is_S else [d_val - 1])

                    for p in range(min_p, max_p + 1):
                        for delta in deltas:
                            np = p + delta
                            if -1 <= np <= 1:
                                if np < n_min: n_min = np
                                if np > n_max: n_max = np
                                found = True

                    if found:
                        ni = interval_to_idx[(n_min, n_max)]
                        new_dp[ni][d0] = (new_dp[ni][d0] + count) % MOD
        dp = new_dp

    ans = 0
    for ii in range(6):
        for d0 in range(4):
            count = dp[ii][d0]
            if count == 0:
                continue

            min_p, max_p = idx_to_interval[ii]
            valid = False
            if not is_S[0]:
                if min_p <= 1 - d0 <= max_p:
                    valid = True
            else:
                if min_p <= 1 - d0 <= max_p or min_p <= 2 - d0 <= max_p:
                    valid = True

            if valid:
                ans = (ans + count) % MOD

    print(ans)

