class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # dp[r][c][d][p] stores the max length of a valid sequence starting at (r,c)
        # in direction d, expecting phase p.
        # p=0 expects 1, p=1 expects 2, p=2 expects 0.
        dp = [[[ [0]*3 for _ in range(4)] for _ in range(m)] for _ in range(n)]
        DIRS = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        for d in range(4):
            dr, dc = DIRS[d]
            # Determine iteration order to ensure dependencies are computed first
            r_start = n - 1 if dr > 0 else 0
            r_end = -1 if dr > 0 else n
            r_step = -1 if dr > 0 else 1

            c_start = m - 1 if dc > 0 else 0
            c_end = -1 if dc > 0 else m
            c_step = -1 if dc > 0 else 1

            for r in range(r_start, r_end, r_step):
                for c in range(c_start, c_end, c_step):
                    for p in range(3):
                        exp = 1 if p == 0 else (2 if p == 1 else 0)
                        if grid[r][c] != exp:
                            dp[r][c][d][p] = 0
                        else:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                next_p = 1 if p == 0 else (2 if p == 1 else 1)
                                dp[r][c][d][p] = 1 + dp[nr][nc][d][next_p]
                            else:
                                dp[r][c][d][p] = 1

        ans = 0
        for r in range(n):
            for c in range(m):
                # Check straight segments (0 turns)
                for d in range(4):
                    if dp[r][c][d][0] > ans:
                        ans = dp[r][c][d][0]

                # Check V-shaped segments with a turn at (r,c)
                for d_in in range(4):
                    dr, dc = DIRS[d_in]
                    pr, pc = r - dr, c - dc
                    if 0 <= pr < n and 0 <= pc < m:
                        L_in = dp[pr][pc][d_in][0]
                        if L_in > 0:
                            # Determine phase at the turn point based on incoming length
                            if L_in == 1:
                                phase = 0
                            elif L_in % 2 == 1:
                                phase = 1
                            else:
                                phase = 2

                            d_out = (d_in + 1) % 4
                            L_out = dp[r][c][d_out][phase]
                            if L_in + L_out - 1 > ans:
                                ans = L_in + L_out - 1

        return ans

import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
        A = [int(next(iterator)) for _ in range(N)]
    except StopIteration:
        return

    V = max(A)

    # Frequency counting. Size V+2 to safely handle boundary checks.
    cnt = [0] * (V + 2)
    for x in A:
        cnt[x] += 1

    # Count multiples of each g efficiently using slicing
    total = [0] * (V + 1)
    for g in range(1, V + 1):
        total[g] = sum(cnt[g::g])

    ans = [1] * (V + 1)

    # DSU parent array. Size V+3 to prevent IndexError when find() traverses past V.
    parent = [i for i in range(V + 3)]
    for i in range(V + 2):
        if cnt[i] == 0:
            parent[i] = i + 1

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    for g in range(V, 0, -1):
        if total[g] >= K:
            m = g
            while m <= V:
                m = find(m)
                if m > V:
                    break
                if m % g != 0:
                    m = (m // g + 1) * g
                    continue
                if cnt[m] > 0 and ans[m] == 1:
                    ans[m] = g
                    parent[m] = find(m + 1)
                m += g

    sys.stdout.write('\n'.join(str(ans[x]) for x in A) + '\n')

