from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(target)
        full_mask = (1 << n) - 1

        # Precompute the minimum cost to satisfy each subset of targets
        cost = [0] * (1 << n)
        for mask in range(1, 1 << n):
            lcm_val = 1
            for i in range(n):
                if mask & (1 << i):
                    lcm_val = lcm_val * target[i] // math.gcd(lcm_val, target[i])

            min_c = float('inf')
            for x in nums:
                rem = x % lcm_val
                c = (lcm_val - rem) % lcm_val
                if c < min_c:
                    min_c = c
            cost[mask] = min_c

        # DP to find the optimal partition of targets
        dp = [float('inf')] * (1 << n)
        dp[0] = 0

        for mask in range(1, 1 << n):
            sub = mask
            while sub > 0:
                if dp[mask ^ sub] + cost[sub] < dp[mask]:
                    dp[mask] = dp[mask ^ sub] + cost[sub]
                sub = (sub - 1) & mask

        return dp[full_mask]

