    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        if N == 1:
            results.append("2 1")
            continue

        # Find a prime M such that M = k*N + 1
        # This ensures M-1 is divisible by N, so elements of order N exist modulo M.
        k = 1
        while True:
            M = k * N + 1
            if is_prime_mr(M):
                break
            k += 1

        # Factorize M-1 = k * N to find all distinct prime factors
        n_factors = get_prime_factors(N)
        k_factors = get_prime_factors(k)
        m_minus_1_factors = n_factors.union(k_factors)

        # Find a primitive root g modulo M
        # A primitive root has order M-1.
        g = 2
        while True:
            is_primitive = True
            for q in m_minus_1_factors:
                if pow(g, (M - 1) // q, M) == 1:
                    is_primitive = False
                    break
            if is_primitive:
                break
            g += 1

        # Compute A = g^((M-1)/N) mod M
        # The order of A modulo M is exactly N.
        A = pow(g, (M - 1) // N, M)
        results.append(f"{A} {M}")

    sys.stdout.write('\n'.join(results) + '\n')

