class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(l, r, k):
            """Count pairs (x, y) with 0 <= x <= l-1, 0 <= y <= r-1, x + y <= k - 1."""
            m = min(l, k)
            t = k - r
            if t >= m - 1:
                # Full rectangle fits within constraint
                return m * r
            elif t < 0:
                # Constraint cuts off entire right side
                return m * k - m * (m - 1) // 2
            else:
                # Partial cut: some full rows, then a triangle
                part1 = (t + 1) * r
                part2 = (2 * k - m - t) * (m - t - 1) // 2
                return part1 + part2

        def compute_contribution(nums, k, is_max):
            n = len(nums)
            L = [-1] * n
            R = [n] * n

            # Find left boundary using monotonic stack
            stack = []
            for i in range(n):
                if is_max:
                    # L[i]: nearest left index where nums[j] > nums[i]
                    while stack and nums[stack[-1]] <= nums[i]:
                        stack.pop()
                else:
                    # L[i]: nearest left index where nums[j] < nums[i]
                    while stack and nums[stack[-1]] >= nums[i]:
                        stack.pop()
                L[i] = stack[-1] if stack else -1
                stack.append(i)

            # Find right boundary using monotonic stack
            stack = []
            for i in range(n - 1, -1, -1):
                if is_max:
                    # R[i]: nearest right index where nums[j] >= nums[i]
                    while stack and nums[stack[-1]] < nums[i]:
                        stack.pop()
                else:
                    # R[i]: nearest right index where nums[j] <= nums[i]
                    while stack and nums[stack[-1]] > nums[i]:
                        stack.pop()
                R[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i in range(n):
                l = i - L[i]  # number of valid start positions
                r = R[i] - i  # number of valid end positions
                count = count_pairs(l, r, k)
                total += nums[i] * count

            return total

        return compute_contribution(nums, k, True) + compute_contribution(nums, k, False)

import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    N = int(next(iterator))
    p = int(next(iterator))

    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(next(iterator)))
        A.append(row)

    if p == 2:
        # For p=2, any path contributes.
        # B is uniquely determined: 0s become 1s.
        B = []
        for i in range(N):
            row = []
            for j in range(N):
                if A[i][j] == 0:
                    row.append(1)
                else:
                    row.append(A[i][j] % 2)
            B.append(row)

        # Compute B^2 mod 2
        res = [[0] * N for _ in range(N)]
        for i in range(N):
            for k in range(N):
                if B[i][k] == 0: continue
                for j in range(N):
                    res[i][j] = (res[i][j] + B[i][k] * B[k][j]) % 2

        for row in res:
            print(' '.join(map(str, row)))
        return

    # For p > 2
    # Compute A_nz^p mod p
    # A_nz has A[i][j] if A[i][j] != 0, else 0
    A_nz = [[0] * N for _ in range(N)]
    zeros = []
    K = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                zeros.append((i, j))
                K += 1
            else:
                A_nz[i][j] = A[i][j] % p

    # Matrix multiplication mod p
    def mat_mul(X, Y):
        Z = [[0] * N for _ in range(N)]
        for i in range(N):
            for k in range(N):
                if X[i][k] == 0: continue
                val = X[i][k]
                for j in range(N):
                    Z[i][j] = (Z[i][j] + val * Y[k][j]) % p
        return Z

    # Matrix exponentiation mod p
    def mat_pow(X, exp):
        res = [[0] * N for _ in range(N)]
        for i in range(N): res[i][i] = 1
        base = X
        while exp > 0:
            if exp % 2 == 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            exp //= 2
        return res

    R = mat_pow(A_nz, p)

    # Multiply by (-1)^K
    if K % 2 == 1:
        for i in range(N):
            for j in range(N):
                R[i][j] = (-R[i][j]) % p

    S = R

    # Add mixed paths
    # For each zero (r, c), if A[c][r] != 0, add contributions
    for r, c in zeros:
        if A[c][r] != 0:
            val = A[c][r] % p
            # S[r][c] += 2 * val
            S[r][c] = (S[r][c] + 2 * val) % p
            # S[c][c] -= val
            S[c][c] = (S[c][c] - val) % p
            # S[r][r] -= val
            S[r][r] = (S[r][r] - val) % p

    for row in S:
        print(' '.join(map(str, row)))

