class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Iterative segment tree
        M = 1
        while M < n:
            M *= 2
        tree = [None] * (2 * M)

        def merge(left, right):
            if left is None: return right
            if right is None: return left
            total_sum = left[0] + right[0]
            max_prefix = max(left[1], left[0] + right[1])
            max_suffix = max(right[2], right[0] + left[2])
            max_subarray = max(left[3], right[3], left[2] + right[1])
            return (total_sum, max_prefix, max_suffix, max_subarray)

        # Initialize leaves
        for i in range(n):
            val = nums[i]
            tree[M + i] = (val, val, val, val)
        for i in range(n, M):
            tree[M + i] = None

        # Build internal nodes
        for i in range(M - 1, 0, -1):
            tree[i] = merge(tree[2*i], tree[2*i+1])

        def query(l, r):
            l += M
            r += M
            left_res = None
            right_res = None
            while l <= r:
                if l % 2 == 1:
                    left_res = merge(left_res, tree[l])
                    l += 1
                if r % 2 == 0:
                    right_res = merge(tree[r], right_res)
                    r -= 1
                l //= 2
                r //= 2
            return merge(left_res, right_res)

        # Precompute positions
        pos = {}
        for i, x in enumerate(nums):
            if x not in pos:
                pos[x] = []
            pos[x].append(i)

        # Initial answer: original array
        ans = tree[1][3]

        # For each distinct value, compute max subarray sum after removal
        for x, indices in pos.items():
            current = None
            prev_end = -1
            for idx in indices:
                if prev_end + 1 <= idx - 1:
                    seg = query(prev_end + 1, idx - 1)
                    current = merge(current, seg)
                prev_end = idx + 1
            if prev_end <= n - 1:
                seg = query(prev_end, n - 1)
                current = merge(current, seg)

            if current is not None:
                ans = max(ans, current[3])

        return ans

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        runs = []
        curr_len = 1
        for i in range(1, n):
            if s[i] == s[i-1]:
                curr_len += 1
            else:
                runs.append(curr_len)
                curr_len = 1
        runs.append(curr_len)

        low, high = 1, n
        ans = n

        while low <= high:
            mid = (low + high) // 2
            flips_needed = sum(L // (mid + 1) for L in runs)
            if flips_needed <= numOps:
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        c = [0] * 26
        for ch in s:
            c[ord(ch) - ord('a')] += 1

        n = len(s)
        ans = n

        # Iterate over all possible target frequencies K
        for K in range(1, n + 1):
            # dp[balance] = min_cost
            dp = {0: 0}

            for count in c:
                new_dp = {}
                for bal, cost in dp.items():
                    # Option 1: Exclude this character from the final set (target count 0)
                    nb = bal + count
                    nc = cost + abs(nb)
                    if nc < ans:
                        if nb not in new_dp or nc < new_dp[nb]:
                            new_dp[nb] = nc

                    # Option 2: Include this character in the final set (target count K)
                    nb = bal + count - K
                    nc = cost + abs(nb)
                    if nc < ans:
                        if nb not in new_dp or nc < new_dp[nb]:
                            new_dp[nb] = nc
                dp = new_dp
                if not dp:
                    break

            if dp:
                ans = min(ans, min(dp.values()))

        return ans

