def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        A = [int(next(iterator)) for _ in range(N)]
    except StopIteration:
        return

    P = [0] * (N + 1)
    for i in range(N):
        P[i+1] = P[i] + A[i]

    B = [P[i+1] + A[i] for i in range(N)]
    E = [P[i] - A[i] for i in range(N)]

    M = 1
    while M < N:
        M *= 2

    tree_max = [0] * (2 * M)
    for i in range(N):
        tree_max[M + i] = B[i]
    for i in range(M - 1, 0, -1):
        tree_max[i] = max(tree_max[2*i], tree_max[2*i+1])

    tree_min = [float('inf')] * (2 * M)
    for i in range(N):
        tree_min[M + i] = E[i]
    for i in range(M - 1, 0, -1):
        tree_min[i] = min(tree_min[2*i], tree_min[2*i+1])

    def find_rightmost_max(l, r, v):
        if l > r:
            return -1
        nodes = []
        L, R = l + M, r + M
        while L <= R:
            if L % 2 == 1:
                nodes.append(L)
                L += 1
            if R % 2 == 0:
                nodes.append(R)
                R -= 1
            L //= 2
            R //= 2
        for idx in reversed(nodes):
            if tree_max[idx] >= v:
                curr = idx
                while curr < M:
                    if tree_max[2*curr+1] >= v:
                        curr = 2*curr+1
                    else:
                        curr = 2*curr
                return curr - M
        return -1

    def find_leftmost_min(l, r, v):
        if l > r:
            return -1
        nodes = []
        L, R = l + M, r + M
        while L <= R:
            if L % 2 == 1:
                nodes.append(L)
                L += 1
            if R % 2 == 0:
                nodes.append(R)
                R -= 1
            L //= 2
            R //= 2
        for idx in nodes:
            if tree_min[idx] <= v:
                curr = idx
                while curr < M:
                    if tree_min[2*curr] <= v:
                        curr = 2*curr
                    else:
                        curr = 2*curr+1
                return curr - M
        return -1

    ans = []
    for k in range(N):
        l_idx = find_rightmost_max(0, k-1, P[k+1])
        L = l_idx + 1 if l_idx != -1 else 0

        r_idx = find_leftmost_min(k+1, N-1, P[L])
        R = r_idx - 1 if r_idx != -1 else N-1

        s = P[R+1] - P[L]
        ans.append(s)

    print(*(ans))

