class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        # Union each number with all its multiples up to threshold.
        # This correctly merges numbers that share a common multiple <= threshold,
        # which is equivalent to lcm(a, b) <= threshold.
        for x in nums:
            if x <= threshold:
                for m in range(2 * x, threshold + 1, x):
                    union(x, m)

        isolated = 0
        roots = set()
        for x in nums:
            if x > threshold:
                isolated += 1
            else:
                roots.add(find(x))

        return isolated + len(roots)
